def batch(group,text):
 for line in text.strip().splitlines():
  if not line.strip(): continue
  p=line.split('|')
  assert len(p)==9,(len(p),line)
  title,math,work,domain,neg,good1,good2,bad,deps=p
  i=876+len(ROWS); branch,fp,base,src=CFG[group]
  dep=[f'AS{int(d):03d}' for d in deps.split(',') if d.strip()]
  # Each row supplies a distinct mathematical target, fixture, and three targeted child obligations.
  ROWS.append(dict(id=f'AS{i}',group=group,title=title,claim_key=re.sub('[^a-z0-9]+','_',title.lower()).strip('_'),
   principle='Resolve the specific implication represented by '+title.lower()+'. Preserve all action terms needed for the stated test; a favorable subblock does not certify the whole theory.',
   math=math,
   inputs=domain+' '+base,
   steps=['Read the pinned equations and import only the listed dependency results, recording their domains before choosing the test variables.',work,'Carry out the calculation on the stated fixture and isolate the residual, bound or rank condition that could invalidate the proposed implication.','Check an independently simplified limit, then apply the explicit negative control. Give the smallest hypothesis needed for extension beyond the tested domain.'],
   checks=['The action-consistent simplified limit and an independent algebraic or numerical evaluation must agree within a declared error.','Negative control: '+neg],
   completion='Deliver the requested relation with its domain, or a concrete obstruction and the failed estimate. Keep finite verification separate from a general proof.',
   sources=[S[z] for z in src.split(',')],branch=branch,depends_on=dep,priority='P1',kind='derivation',
   first_principles=fp,
   closure_bridge='This establishes or blocks '+work[0].lower()+work[1:]+ ' It is one necessary link toward the same-action closure requirements.',
   continuation=['If promising: '+good1,'If promising: '+good2,'If failed: '+bad]))

