# Semantic dedup revisions agreed with the catalog coordinator; identifiers stay fixed.
def revise(n,title,principle,math,inputs,steps,checks,bridge,children,deps,kind='derivation'):
 r=ROWS[n-876]
 r.update(title=title,claim_key=re.sub('[^a-z0-9]+','_',title.lower()).strip('_'),
 principle=principle,math=math,inputs=inputs+' '+CFG[r['group']][2],steps=steps,checks=checks,
 closure_bridge=bridge,continuation=['If promising: '+children[0],'If promising: '+children[1],'If failed: '+children[2]],
 depends_on=[f'AS{x:03d}' for x in deps],kind=kind)

